/**
 * Sage Migration API
 * GET  /api/accounting/sage-migration              — migration status dashboard
 * GET  /api/accounting/sage-migration?view=mappings — account mappings list
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import {
  getMigrationStatus,
  getAccountMappings,
} from '@/modules/accounting/services/sageMigrationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const view = String(req.query.view || 'status');

  if (view === 'mappings') {
    const mappings = await getAccountMappings(companyId);
    return apiResponse.success(res, mappings);
  }

  const status = await getMigrationStatus(companyId);
  return apiResponse.success(res, status);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Sage Migration Actions API
 * POST /api/accounting/sage-migration-action
 *
 * Actions: auto_map, manual_map, import_ledger, import_invoices, compare, reset
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  autoMapAccounts,
  mapAccount,
  importLedgerTransactions,
  importSupplierInvoices,
  importCustomerInvoices,
  generateComparison,
  resetMigration,
} from '@/modules/accounting/services/sageMigrationService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const userId = req.user.id;
  const { action } = req.body;

  if (!action) {
    return apiResponse.badRequest(res, 'action is required');
  }

  log.info(`Sage migration action: ${action}`, { userId }, 'accounting');

  switch (action) {
    case 'auto_map': {
      const run = await autoMapAccounts(companyId, userId);
      return apiResponse.success(res, run);
    }

    case 'manual_map': {
      const { sageAccountId, glAccountId, notes } = req.body;
      if (!sageAccountId) return apiResponse.badRequest(res, 'sageAccountId is required');
      await mapAccount(companyId, sageAccountId, glAccountId || null, notes);
      return apiResponse.success(res, { mapped: true });
    }

    case 'import_ledger': {
      const run = await importLedgerTransactions(companyId, userId);
      return apiResponse.success(res, run);
    }

    case 'import_invoices': {
      const run = await importSupplierInvoices(companyId, userId);
      return apiResponse.success(res, run);
    }

    case 'import_customer_invoices': {
      const run = await importCustomerInvoices(companyId, userId);
      return apiResponse.success(res, run);
    }

    case 'compare': {
      const report = await generateComparison(companyId, userId);
      return apiResponse.success(res, report);
    }

    case 'reset': {
      const { resetType, confirm } = req.body;
      if (!resetType || !['accounts', 'ledger', 'invoices', 'customer_invoices'].includes(resetType)) {
        return apiResponse.badRequest(res, 'resetType must be accounts, ledger, invoices, or customer_invoices');
      }
      if (confirm !== true) {
        return apiResponse.badRequest(res, 'Reset requires { confirm: true } to prevent accidental data loss');
      }
      log.warn('Sage migration reset initiated', {
        resetType,
        userId,
        timestamp: new Date().toISOString(),
      }, 'sage-migration');
      await resetMigration(companyId, resetType);
      return apiResponse.success(res, { reset: resetType });
    }

    default:
      return apiResponse.badRequest(res, `Unknown action: ${action}`);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withRole('admin')(withErrorHandler(handler)));

/**
 * Sage Auto-Pull API
 * GET /api/accounting/migration/sage-pull?step=scripts
 *   → Returns JavaScript snippets the browser extension injects into Sage
 *
 * POST /api/accounting/migration/sage-pull
 *   → Receives raw Sage data from the browser, maps to ISAFlow format, returns mapped data
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withRole } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  buildSageAccountsFetchScript,
  buildSageFetchScript,
  buildSageCompanyFetchScript,
  mapSageAccounts,
  mapSageCustomers,
  mapSageSuppliers,
  mapSageARInvoices,
  mapSageAPInvoices,
} from '@/modules/accounting/services/sageAutoImportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    // Return the JS scripts the browser extension will inject into Sage
    const scripts = {
      company: buildSageCompanyFetchScript(),
      accounts: buildSageAccountsFetchScript(),
      customers: buildSageFetchScript('/services/Customer/GetWithFilter', 200),
      suppliers: buildSageFetchScript('/services/Supplier/GetWithFilter', 200),
      arInvoices: buildSageFetchScript('/services/TaxInvoice/GetWithFilter', 200),
      apInvoices: buildSageFetchScript('/services/SupplierInvoice/GetWithFilter', 200),
    };

    return apiResponse.success(res, { scripts });
  }

  if (req.method === 'POST') {
    const { step, rawData } = req.body as { step: string; rawData: unknown };

    if (!step || !rawData) {
      return apiResponse.validationError(res, { step: 'step and rawData are required' });
    }

    log.info('Sage auto-pull received', { companyId, step }, 'migration');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const data = rawData as any;

    switch (step) {
      case 'accounts': {
        const mapped = mapSageAccounts(data.Results || []);
        return apiResponse.success(res, {
          step: 'accounts',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'customers': {
        const mapped = mapSageCustomers(data.Results || []);
        return apiResponse.success(res, {
          step: 'customers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'suppliers': {
        const mapped = mapSageSuppliers(data.Results || []);
        return apiResponse.success(res, {
          step: 'suppliers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'arInvoices': {
        const mapped = mapSageARInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'arInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'apInvoices': {
        const mapped = mapSageAPInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'apInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'company': {
        return apiResponse.success(res, {
          step: 'company',
          record: {
            name: data.Name,
            taxNumber: data.TaxNumber,
            registrationNumber: data.RegistrationNumber,
            currency: data.CurrencySymbol,
            takeOnDate: data.TakeOnBalanceDate,
          },
        });
      }
      default:
        return apiResponse.badRequest(res, `Unknown step: ${step}`);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// Super admin only — ISAFlow internal tool
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withRole('super_admin')(withErrorHandler(handler)) as any);

/**
 * Sage Migration Dashboard
 * PRD-060 Phase 6: Import Sage data into native GL
 *
 * Step 1: Map sage_accounts → gl_accounts
 * Step 2: Import sage_ledger_transactions → gl_journal_entries
 * Step 3: Import sage_supplier_invoices → supplier_invoices
 * Step 4: Compare Sage vs GL balances
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ArrowLeft, Database, ArrowRightLeft, FileSpreadsheet, Receipt,
  BarChart3, Loader2, AlertCircle, CheckCircle2, Play, RotateCcw,
} from 'lucide-react';
import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface MigrationStatus {
  accounts: { sageTotal: number; mapped: number; unmapped: number; autoMapped: number };
  ledger: { sageTotal: number; imported: number; pending: number; failed: number; dateRange: { earliest: string | null; latest: string | null } };
  invoices: { sageTotal: number; imported: number; pending: number; failed: number };
  lastRuns: Array<{ id: string; runType: string; status: string; totalRecords: number; succeeded: number; failed: number; skipped: number; startedAt: string; completedAt: string | null }>;
}

interface ComparisonReport {
  comparisonDate: string;
  sageTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  glTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  differences: Array<{ accountCode: string; accountName: string; sageBalance: number; glBalance: number; difference: number }>;
  isBalanced: boolean;
}

export default function SageMigrationPage() {
  const [status, setStatus] = useState<MigrationStatus | null>(null);
  const [comparison, setComparison] = useState<ComparisonReport | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState('');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');

  const loadStatus = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/sage-migration');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load');
      setStatus(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load migration status');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadStatus(); }, [loadStatus]);

  const runAction = async (action: string, extra?: Record<string, string>) => {
    setActionLoading(action);
    setError('');
    setMessage('');
    try {
      const res = await apiFetch('/api/accounting/sage-migration-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, ...extra }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Action failed');

      const data = json.data || json;

      if (action === 'compare') {
        setComparison(data);
        setMessage('Comparison report generated');
      } else if (action === 'reset') {
        setMessage(`Reset ${extra?.resetType} migration status`);
      } else {
        const run = data;
        setMessage(`${action}: ${run.succeeded} succeeded, ${run.failed} failed, ${run.skipped} skipped`);
      }

      await loadStatus();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally {
      setActionLoading('');
    }
  };

  const noSageData = status && status.accounts.sageTotal === 0 && status.ledger.sageTotal === 0 && status.invoices.sageTotal === 0;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Accounting
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-orange-500/10">
                <Database className="h-6 w-6 text-orange-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Sage Migration</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Import Sage data into native General Ledger</p>
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-5xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}
          {message && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm">
              <CheckCircle2 className="h-4 w-4" /> {message}
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-orange-500" />
            </div>
          ) : noSageData ? (
            <div className="space-y-4">
              <div className="p-8 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] text-center">
                <Database className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-4" />
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">No Sage Data to Migrate</h2>
                <p className="text-[var(--ff-text-secondary)] max-w-lg mx-auto mb-4">
                  The Sage sync tables are empty. Once Sage data is synced to the local database
                  (sage_accounts, sage_ledger_transactions, sage_supplier_invoices),
                  return here to run the migration pipeline.
                </p>
                <div className="grid grid-cols-4 gap-4 mt-6 text-left">
                  <StepCard
                    step={1}
                    icon={<ArrowRightLeft className="h-5 w-5" />}
                    title="Map Accounts"
                    desc="Auto-map Sage accounts to GL chart of accounts"
                    status="waiting"
                  />
                  <StepCard
                    step={2}
                    icon={<FileSpreadsheet className="h-5 w-5" />}
                    title="Import Ledger"
                    desc="Convert Sage transactions to journal entries"
                    status="waiting"
                  />
                  <StepCard
                    step={3}
                    icon={<Receipt className="h-5 w-5" />}
                    title="Import Invoices"
                    desc="Migrate supplier invoices to AP module"
                    status="waiting"
                  />
                  <StepCard
                    step={4}
                    icon={<BarChart3 className="h-5 w-5" />}
                    title="Compare"
                    desc="Validate Sage vs GL balances match"
                    status="waiting"
                  />
                </div>
              </div>

              <div className="p-4 rounded-lg bg-blue-500/10 border border-blue-500/20 text-sm">
                <p className="font-semibold text-blue-400 mb-1">How to sync Sage data</p>
                <p className="text-[var(--ff-text-secondary)]">
                  Use the Sage sync APIs to pull data:
                  <code className="mx-1 px-1.5 py-0.5 rounded bg-[var(--ff-bg-primary)] text-xs font-mono">POST /api/sage/sync/chart-of-accounts</code>
                  and
                  <code className="mx-1 px-1.5 py-0.5 rounded bg-[var(--ff-bg-primary)] text-xs font-mono">POST /api/sage/sync/invoices</code>
                </p>
              </div>
            </div>
          ) : status ? (
            <div className="space-y-6">
              {/* Step 1: Account Mapping */}
              <MigrationStep
                step={1}
                icon={<ArrowRightLeft className="h-5 w-5 text-blue-400" />}
                title="Account Mapping"
                desc={`${status.accounts.mapped}/${status.accounts.sageTotal} accounts mapped (${status.accounts.autoMapped} auto)`}
                progress={status.accounts.sageTotal > 0 ? (status.accounts.mapped / status.accounts.sageTotal) * 100 : 0}
                complete={status.accounts.sageTotal > 0 && status.accounts.unmapped === 0}
                onRun={() => runAction('auto_map')}
                onReset={() => runAction('reset', { resetType: 'accounts' })}
                loading={actionLoading === 'auto_map'}
                runLabel="Auto-Map"
              />

              {/* Step 2: Ledger Import */}
              <MigrationStep
                step={2}
                icon={<FileSpreadsheet className="h-5 w-5 text-purple-400" />}
                title="Ledger Transaction Import"
                desc={`${status.ledger.imported}/${status.ledger.sageTotal} transactions imported${status.ledger.failed > 0 ? `, ${status.ledger.failed} failed` : ''}`}
                progress={status.ledger.sageTotal > 0 ? (status.ledger.imported / status.ledger.sageTotal) * 100 : 0}
                complete={status.ledger.sageTotal > 0 && status.ledger.pending === 0}
                onRun={() => runAction('import_ledger')}
                onReset={() => runAction('reset', { resetType: 'ledger' })}
                loading={actionLoading === 'import_ledger'}
                runLabel="Import"
                disabled={status.accounts.unmapped > 0}
                disabledReason="Map all accounts first"
              />

              {/* Step 3: Invoice Import */}
              <MigrationStep
                step={3}
                icon={<Receipt className="h-5 w-5 text-amber-400" />}
                title="Supplier Invoice Import"
                desc={`${status.invoices.imported}/${status.invoices.sageTotal} invoices imported${status.invoices.failed > 0 ? `, ${status.invoices.failed} failed` : ''}`}
                progress={status.invoices.sageTotal > 0 ? (status.invoices.imported / status.invoices.sageTotal) * 100 : 0}
                complete={status.invoices.sageTotal > 0 && status.invoices.pending === 0}
                onRun={() => runAction('import_invoices')}
                onReset={() => runAction('reset', { resetType: 'invoices' })}
                loading={actionLoading === 'import_invoices'}
                runLabel="Import"
              />

              {/* Step 4: Comparison */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="flex items-center justify-center w-8 h-8 rounded-full bg-teal-500/10 text-teal-400 text-sm font-bold">4</div>
                    <div>
                      <h3 className="font-semibold text-[var(--ff-text-primary)]">Parallel Run Comparison</h3>
                      <p className="text-xs text-[var(--ff-text-secondary)]">Compare Sage balances vs GL balances for validation</p>
                    </div>
                  </div>
                  <button
                    onClick={() => runAction('compare')}
                    disabled={actionLoading === 'compare'}
                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-500 text-white text-sm font-medium disabled:opacity-50"
                  >
                    {actionLoading === 'compare' ? <Loader2 className="h-4 w-4 animate-spin" /> : <BarChart3 className="h-4 w-4" />}
                    Run Comparison
                  </button>
                </div>

                {comparison && (
                  <div className="space-y-3 mt-4">
                    <div className="grid grid-cols-3 gap-3">
                      <div className="p-3 rounded-lg bg-[var(--ff-bg-primary)]">
                        <p className="text-xs text-[var(--ff-text-tertiary)]">Sage Accounts</p>
                        <p className="text-lg font-bold text-[var(--ff-text-primary)]">{comparison.sageTotals.accountCount}</p>
                      </div>
                      <div className="p-3 rounded-lg bg-[var(--ff-bg-primary)]">
                        <p className="text-xs text-[var(--ff-text-tertiary)]">GL Accounts</p>
                        <p className="text-lg font-bold text-[var(--ff-text-primary)]">{comparison.glTotals.accountCount}</p>
                      </div>
                      <div className={`p-3 rounded-lg ${comparison.isBalanced ? 'bg-teal-500/10' : 'bg-red-500/10'}`}>
                        <p className="text-xs text-[var(--ff-text-tertiary)]">Status</p>
                        <p className={`text-lg font-bold ${comparison.isBalanced ? 'text-teal-400' : 'text-red-400'}`}>
                          {comparison.isBalanced ? 'Balanced' : `${comparison.differences.length} Differences`}
                        </p>
                      </div>
                    </div>

                    {comparison.differences.length > 0 && (
                      <div className="rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                        <table className="w-full text-sm">
                          <thead>
                            <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)]">
                              <th className="text-left px-3 py-2 text-[var(--ff-text-secondary)]">Account</th>
                              <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">Sage</th>
                              <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">GL</th>
                              <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">Diff</th>
                            </tr>
                          </thead>
                          <tbody>
                            {comparison.differences.map(d => (
                              <tr key={d.accountCode} className="border-b border-[var(--ff-border-light)]">
                                <td className="px-3 py-2 text-[var(--ff-text-primary)]">
                                  <span className="font-mono text-xs mr-2">{d.accountCode}</span>{d.accountName}
                                </td>
                                <td className="px-3 py-2 text-right font-mono">{formatCurrency(d.sageBalance)}</td>
                                <td className="px-3 py-2 text-right font-mono">{formatCurrency(d.glBalance)}</td>
                                <td className="px-3 py-2 text-right font-mono text-red-400">{formatCurrency(d.difference)}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Migration History */}
              {status.lastRuns.length > 0 && (
                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
                  <div className="px-5 py-3 border-b border-[var(--ff-border-light)]">
                    <h3 className="font-semibold text-[var(--ff-text-primary)]">Migration History</h3>
                  </div>
                  <div className="divide-y divide-[var(--ff-border-light)]">
                    {status.lastRuns.map(run => (
                      <div key={run.id} className="px-5 py-3 flex items-center justify-between text-sm">
                        <div>
                          <span className="font-medium text-[var(--ff-text-primary)]">{run.runType.replace('_', ' ')}</span>
                          <span className="text-[var(--ff-text-tertiary)] text-xs ml-2">
                            {new Date(run.startedAt).toLocaleDateString('en-ZA')}
                          </span>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="text-xs text-[var(--ff-text-secondary)]">
                            {run.succeeded} ok / {run.failed} fail / {run.skipped} skip
                          </span>
                          <StatusBadge status={run.status} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

function StepCard({ step, icon, title, desc, status }: {
  step: number;
  icon: React.ReactNode;
  title: string;
  desc: string;
  status: 'waiting' | 'ready' | 'done';
}) {
  return (
    <div className="p-4 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)]">
      <div className="flex items-center gap-2 mb-2">
        <span className="flex items-center justify-center w-6 h-6 rounded-full bg-[var(--ff-bg-secondary)] text-[var(--ff-text-tertiary)] text-xs font-bold">{step}</span>
        <span className="text-[var(--ff-text-tertiary)]">{icon}</span>
      </div>
      <p className="text-sm font-medium text-[var(--ff-text-primary)]">{title}</p>
      <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">{desc}</p>
      {status === 'waiting' && <p className="text-xs text-[var(--ff-text-tertiary)] mt-2 italic">Waiting for data</p>}
    </div>
  );
}

function MigrationStep({ step, icon, title, desc, progress, complete, onRun, onReset, loading, runLabel, disabled, disabledReason }: {
  step: number;
  icon: React.ReactNode;
  title: string;
  desc: string;
  progress: number;
  complete: boolean;
  onRun: () => void;
  onReset: () => void;
  loading: boolean;
  runLabel: string;
  disabled?: boolean;
  disabledReason?: string;
}) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-3">
          <div className={`flex items-center justify-center w-8 h-8 rounded-full text-sm font-bold ${complete ? 'bg-teal-500/10 text-teal-400' : 'bg-blue-500/10 text-blue-400'}`}>
            {complete ? <CheckCircle2 className="h-4 w-4" /> : step}
          </div>
          <div>
            <h3 className="font-semibold text-[var(--ff-text-primary)] flex items-center gap-2">
              {icon} {title}
            </h3>
            <p className="text-xs text-[var(--ff-text-secondary)]">{desc}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={onReset}
            className="p-2 rounded-lg text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-primary)] transition-colors"
            title="Reset"
          >
            <RotateCcw className="h-4 w-4" />
          </button>
          <button
            onClick={onRun}
            disabled={loading || disabled}
            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium disabled:opacity-50"
            title={disabled ? disabledReason : undefined}
          >
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
            {runLabel}
          </button>
        </div>
      </div>
      <div className="h-2 rounded-full bg-[var(--ff-bg-primary)] overflow-hidden">
        <div
          className={`h-full rounded-full transition-all ${complete ? 'bg-teal-500' : 'bg-blue-500'}`}
          style={{ width: `${Math.min(progress, 100)}%` }}
        />
      </div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    completed: 'bg-teal-500/20 text-teal-400',
    partial: 'bg-amber-500/20 text-amber-400',
    failed: 'bg-red-500/20 text-red-400',
    running: 'bg-blue-500/20 text-blue-400',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

/**
 * Sage Auto-Import Page
 *
 * Flow:
 * 1. User logs into Sage in a separate browser tab
 * 2. User opens this page and clicks "Connect to Sage"
 * 3. ISAFlow opens a popup/iframe to accounting.sageone.co.za
 * 4. JavaScript runs inside that context (same-session cookies)
 * 5. Each step pulls data from Sage's internal APIs
 * 6. Data is mapped and previewed before import
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { useAuth } from '@/contexts/AuthContext';
import {
  ArrowLeft, Download, CheckCircle2, AlertCircle,
  Loader2, Database, Users, Building2, FileText, ShieldCheck,
  ExternalLink, RefreshCw,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface PullStep {
  id: string;
  label: string;
  icon: typeof Database;
  description: string;
  status: 'pending' | 'pulling' | 'done' | 'error';
  count?: number;
  error?: string;
}

const INITIAL_STEPS: PullStep[] = [
  { id: 'company', label: 'Company Info', icon: Building2, description: 'Name, tax number, registration', status: 'pending' },
  { id: 'accounts', label: 'Chart of Accounts', icon: Database, description: 'All GL accounts with categories', status: 'pending' },
  { id: 'customers', label: 'Customers', icon: Users, description: 'Customer contacts and balances', status: 'pending' },
  { id: 'suppliers', label: 'Suppliers', icon: Building2, description: 'Supplier contacts and balances', status: 'pending' },
  { id: 'arInvoices', label: 'Customer Invoices (AR)', icon: FileText, description: 'Outstanding sales invoices', status: 'pending' },
  { id: 'apInvoices', label: 'Supplier Invoices (AP)', icon: FileText, description: 'Outstanding purchase invoices', status: 'pending' },
];

export default function SageAutoImportPage() {
  const { user } = useAuth();
  const router = useRouter();
  const [steps, setSteps] = useState<PullStep[]>(INITIAL_STEPS);
  const [connected, setConnected] = useState(false);
  const [pulling, setPulling] = useState(false);
  const [error, setError] = useState('');
  const [sageWindow, setSageWindow] = useState<Window | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const pulledData = useRef<Record<string, any>>({});

  // Super admin only — redirect others
  useEffect(() => {
    if (user && user.role !== 'super_admin') {
      router.replace('/accounting/migration');
    }
  }, [user, router]);

  const updateStep = useCallback((id: string, update: Partial<PullStep>) => {
    setSteps(prev => prev.map(s => s.id === id ? { ...s, ...update } : s));
  }, []);

  const openSageTab = useCallback(() => {
    const win = window.open('https://accounting.sageone.co.za/Dashboard/Home.aspx', 'sage_session');
    if (win) {
      setSageWindow(win);
      setConnected(true);
      setError('');
    } else {
      setError('Popup blocked — please allow popups for this site');
    }
  }, []);

  const runScriptInSage = useCallback(async (script: string): Promise<unknown> => {
    // We can't inject JS into a cross-origin window directly.
    // Instead, we use the fetch approach: the user's Sage tab has cookies,
    // but we call from ISAFlow's context. Since the Sage APIs accept
    // same-origin requests with cookies, we need to proxy through Sage's domain.
    //
    // Alternative approach: execute the fetch from THIS page using the
    // Sage domain — this won't work due to CORS.
    //
    // The working approach: use a message channel with the Sage popup.
    // But since we can't inject into cross-origin, we use the simplest method:
    // fetch from the SERVER side using the session cookies the user provides.
    //
    // ACTUAL working approach for browser automation:
    // The Chrome extension (Claude-in-Chrome) or DevTools MCP can run JS
    // in the Sage tab. For the production flow, we use an approach where
    // the user copies a bookmarklet or we use a browser extension.
    //
    // For now: direct fetch from this page won't work (CORS).
    // We'll use the postMessage approach with a helper page.

    return new Promise((resolve, reject) => {
      if (!sageWindow || sageWindow.closed) {
        reject(new Error('Sage window is closed. Please reconnect.'));
        return;
      }

      // Try direct evaluation via the sage window
      try {
        // This will only work if same-origin (won't work cross-domain)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const result = (sageWindow as any).eval(script);
        if (result && typeof result.then === 'function') {
          result.then(resolve).catch(reject);
        } else {
          resolve(result);
        }
      } catch {
        reject(new Error('Cannot access Sage window — cross-origin restriction. Use the bookmarklet method instead.'));
      }
    });
  }, [sageWindow]);

  const pullAllData = useCallback(async () => {
    setPulling(true);
    setError('');

    try {
      // Get the fetch scripts from our API
      const scriptsRes = await apiFetch('/api/accounting/migration/sage-pull');
      const scriptsJson = await scriptsRes.json();
      if (!scriptsRes.ok) throw new Error('Failed to load pull scripts');
      const scripts = scriptsJson.data.scripts as Record<string, string>;

      // Run each step
      for (const step of INITIAL_STEPS) {
        updateStep(step.id, { status: 'pulling' });
        try {
          const rawData = await runScriptInSage(scripts[step.id] || '');

          // Send raw data to our API for mapping
          const mapRes = await apiFetch('/api/accounting/migration/sage-pull', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ step: step.id, rawData }),
          });
          const mapJson = await mapRes.json();
          if (!mapRes.ok) throw new Error(mapJson.message || 'Mapping failed');

          pulledData.current[step.id] = mapJson.data;
          updateStep(step.id, {
            status: 'done',
            count: mapJson.data.total ?? mapJson.data.records?.length ?? 1,
          });
        } catch (err) {
          const msg = err instanceof Error ? err.message : 'Pull failed';
          updateStep(step.id, { status: 'error', error: msg });
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to pull data');
    } finally {
      setPulling(false);
    }
  }, [runScriptInSage, updateStep]);

  const allDone = steps.every(s => s.status === 'done');
  const anyError = steps.some(s => s.status === 'error');

  return (
    <AppLayout>
      <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Link href="/accounting/migration" className="flex items-center gap-2 text-blue-600 hover:text-blue-800 mb-6 text-sm">
          <ArrowLeft className="h-4 w-4" /> Back to Migration Hub
        </Link>

        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 rounded-lg bg-green-500/10">
            <Download className="h-6 w-6 text-green-500" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Auto-Import from Sage</h1>
            <p className="text-sm text-[var(--ff-text-secondary)]">Pull data directly from your Sage Business Cloud account</p>
          </div>
        </div>

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
            <AlertCircle className="h-4 w-4 shrink-0" /> {error}
          </div>
        )}

        {/* Step 1: Connect */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mb-6">
          <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">Step 1: Connect to Sage</h2>
          <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
            Open Sage Business Cloud in a new window. Make sure you&apos;re logged in and
            have selected the correct company. ISAFlow will read data from your active session.
          </p>
          <div className="flex items-center gap-3">
            <button
              onClick={openSageTab}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-500 text-sm font-medium"
            >
              <ExternalLink className="h-4 w-4" />
              {connected ? 'Reconnect to Sage' : 'Open Sage'}
            </button>
            {connected && (
              <span className="flex items-center gap-1 text-sm text-green-400">
                <CheckCircle2 className="h-4 w-4" /> Sage window open
              </span>
            )}
          </div>
        </div>

        {/* Step 2: Pull Data */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-[var(--ff-text-primary)]">Step 2: Pull Data</h2>
            <button
              onClick={pullAllData}
              disabled={!connected || pulling}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 text-sm font-medium"
            >
              {pulling ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              {pulling ? 'Pulling...' : 'Pull All Data'}
            </button>
          </div>

