    invoiceDate: inv.Date?.split('T')[0] || '',
    dueDate: inv.DueDate?.split('T')[0] || '',
    subtotal: inv.Exclusive,
    taxAmount: inv.Tax,
    totalAmount: inv.Total,
    amountPaid: inv.Total - inv.AmountDue,
