import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// Re-export importers so API routes import from one place
export { importLedgerTransactions, importSupplierInvoices } from './sageImportService';
export { importCustomerInvoices } from './sageCustomerImportService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ───────────────────────────────────────────────────────────────────

export interface MigrationStatus {
  accounts: { sageTotal: number; mapped: number; unmapped: number; autoMapped: number };
  ledger: { sageTotal: number; imported: number; pending: number; failed: number; dateRange: { earliest: string | null; latest: string | null } };
  invoices: { sageTotal: number; imported: number; pending: number; failed: number };
  customerInvoices: { sageTotal: number; imported: number; pending: number; failed: number };
  lastRuns: MigrationRun[];
}

export interface MigrationRun {
  id: string; runType: string; status: string; totalRecords: number;
  processed: number; succeeded: number; failed: number; skipped: number;
  startedAt: string; completedAt: string | null;
}

export interface AccountMapping {
  sageAccountId: string; sageName: string; sageType: number | null; sageBalance: number;
  glAccountId: string | null; glAccountCode: string | null; glAccountName: string | null;
  mappingStatus: string; mappingNotes: string | null;
}

export interface ComparisonReport {
  comparisonDate: string;
  sageTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  glTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  differences: Array<{ accountCode: string; accountName: string; sageBalance: number; glBalance: number; difference: number }>;
  isBalanced: boolean;
}

// ── Run Tracking (exported for sageImportService) ───────────────────────────

export async function startRun(runType: string, userId: string): Promise<string> {
  const rows = (await sql`
    INSERT INTO gl_migration_runs (run_type, status, started_by)
    VALUES (${runType}, 'running', ${userId})
    RETURNING id
  `) as Row[];
  return String(rows[0].id);
}

export async function completeRun(
  runId: string, total: number, succeeded: number, failed: number, skipped: number
): Promise<MigrationRun> {
  const status = failed === 0 ? 'completed' : 'partial';
  const rows = (await sql`
    UPDATE gl_migration_runs
    SET status = ${status}, total_records = ${total}, processed = ${succeeded + failed + skipped},
        succeeded = ${succeeded}, failed = ${failed}, skipped = ${skipped}, completed_at = NOW()
    WHERE id = ${runId}::UUID RETURNING *
  `) as Row[];
  const r = rows[0];
  return {
    id: String(r.id), runType: String(r.run_type), status: String(r.status),
    totalRecords: Number(r.total_records), processed: Number(r.processed),
    succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
    startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
  };
}

export async function failRun(runId: string, err: unknown): Promise<void> {
  const msg = err instanceof Error ? err.message : 'Unknown error';
  await sql`
    UPDATE gl_migration_runs SET status = 'failed', error_message = ${msg}, completed_at = NOW()
    WHERE id = ${runId}::UUID
  `;
}

// ── Migration Status ────────────────────────────────────────────────────────

export async function getMigrationStatus(companyId: string): Promise<MigrationStatus> {
  try {
    const accountStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE gl_account_id IS NOT NULL) AS mapped,
        COUNT(*) FILTER (WHERE gl_account_id IS NULL) AS unmapped,
        COUNT(*) FILTER (WHERE mapping_status = 'auto') AS auto_mapped
      FROM sage_accounts
    `) as Row[];

    const ledgerStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed,
        MIN(transaction_date) AS earliest, MAX(transaction_date) AS latest
      FROM sage_ledger_transactions
    `) as Row[];

    const invoiceStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
      FROM sage_supplier_invoices
    `) as Row[];

    let customerInvoiceStats: Row[] = [{ total: 0, imported: 0, pending: 0, failed: 0 }];
    try {
      customerInvoiceStats = (await sql`
        SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
          COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
          COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
        FROM sage_customer_invoices
      `) as Row[];
    } catch {
      // Table may not exist yet if migration 212 hasn't run
    }

    const runs = (await sql`
      SELECT id, run_type, status, total_records, processed, succeeded, failed, skipped,
        started_at, completed_at
      FROM gl_migration_runs ORDER BY started_at DESC LIMIT 10
    `) as Row[];

    return {
      accounts: {
        sageTotal: Number(accountStats[0]?.total || 0), mapped: Number(accountStats[0]?.mapped || 0),
        unmapped: Number(accountStats[0]?.unmapped || 0), autoMapped: Number(accountStats[0]?.auto_mapped || 0),
      },
      ledger: {
        sageTotal: Number(ledgerStats[0]?.total || 0), imported: Number(ledgerStats[0]?.imported || 0),
        pending: Number(ledgerStats[0]?.pending || 0), failed: Number(ledgerStats[0]?.failed || 0),
        dateRange: { earliest: ledgerStats[0]?.earliest || null, latest: ledgerStats[0]?.latest || null },
      },
      invoices: {
        sageTotal: Number(invoiceStats[0]?.total || 0), imported: Number(invoiceStats[0]?.imported || 0),
        pending: Number(invoiceStats[0]?.pending || 0), failed: Number(invoiceStats[0]?.failed || 0),
      },
      customerInvoices: {
        sageTotal: Number(customerInvoiceStats[0]?.total || 0),
        imported: Number(customerInvoiceStats[0]?.imported || 0),
        pending: Number(customerInvoiceStats[0]?.pending || 0),
        failed: Number(customerInvoiceStats[0]?.failed || 0),
      },
      lastRuns: runs.map((r: Row) => ({
        id: String(r.id), runType: String(r.run_type), status: String(r.status),
        totalRecords: Number(r.total_records), processed: Number(r.processed),
        succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
        startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
      })),
    };
  } catch (err) {
    log.error('Failed to get migration status', { error: err }, 'accounting');
    throw err;
  }
}

// ── Account Mapping ─────────────────────────────────────────────────────────

export async function getAccountMappings(companyId: string): Promise<AccountMapping[]> {
  const rows = (await sql`
    SELECT sa.sage_account_id, sa.name, sa.account_type, sa.balance,
      sa.gl_account_id, sa.mapping_status, sa.mapping_notes,
      ga.account_code, ga.account_name
    FROM sage_accounts sa LEFT JOIN gl_accounts ga ON ga.id = sa.gl_account_id
    ORDER BY sa.name
  `) as Row[];

  return rows.map((r: Row) => ({
    sageAccountId: String(r.sage_account_id), sageName: String(r.name),
    sageType: r.account_type != null ? Number(r.account_type) : null,
    sageBalance: Number(r.balance || 0),
    glAccountId: r.gl_account_id ? String(r.gl_account_id) : null,
    glAccountCode: r.account_code ? String(r.account_code) : null,
    glAccountName: r.account_name ? String(r.account_name) : null,
    mappingStatus: String(r.mapping_status || 'unmapped'),
    mappingNotes: r.mapping_notes ? String(r.mapping_notes) : null,
  }));
}

function nameSimilarity(a: string, b: string): number {
  const tokensA = new Set(a.split(/[\s\-_&/]+/).filter(Boolean));
  const tokensB = new Set(b.split(/[\s\-_&/]+/).filter(Boolean));
  if (tokensA.size === 0 || tokensB.size === 0) return 0;
  let overlap = 0;
  for (const t of tokensA) {
    if (tokensB.has(t)) overlap++;
    else { for (const tb of tokensB) { if (tb.includes(t) || t.includes(tb)) { overlap += 0.5; break; } } }
  }
  return overlap / Math.max(tokensA.size, tokensB.size);
}

export async function autoMapAccounts(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('account_mapping', userId);
  try {
    const sageAccounts = (await sql`
      SELECT id, sage_account_id, name, account_type, balance FROM sage_accounts WHERE gl_account_id IS NULL ORDER BY name
    `) as Row[];
    const glAccounts = (await sql`
      SELECT id, account_code, account_name, account_type FROM gl_accounts WHERE level >= 3 AND is_active = true ORDER BY account_code
    `) as Row[];

    let succeeded = 0; let skipped = 0;
    const typeMap: Record<number, string> = { 1: 'revenue', 2: 'expense', 5: 'asset', 6: 'liability', 7: 'equity' };

    for (const sage of sageAccounts) {
      const sageName = String(sage.name).toLowerCase().trim();
      const sageType = sage.account_type != null ? typeMap[Number(sage.account_type)] : null;
      let bestMatch: Row | null = null; let bestScore = 0;

      for (const gl of glAccounts) {
        if (sageType && String(gl.account_type) !== sageType) continue;
        const score = nameSimilarity(sageName, String(gl.account_name).toLowerCase().trim());
        if (score > bestScore && score >= 0.6) { bestScore = score; bestMatch = gl; }
      }

      if (bestMatch) {
        await sql`
          UPDATE sage_accounts SET gl_account_id = ${bestMatch.id}::UUID, mapping_status = 'auto',
            mapping_notes = ${`Auto-mapped (${(bestScore * 100).toFixed(0)}% match) to ${bestMatch.account_code}`}
          WHERE id = ${sage.id}
        `;
        succeeded++;
      } else { skipped++; }
    }
    return await completeRun(runId, sageAccounts.length, succeeded, 0, skipped);
  } catch (err) { await failRun(runId, err); throw err; }
}

export async function mapAccount(companyId: string, sageAccountId: string, glAccountId: string | null, notes?: string): Promise<void> {
  if (glAccountId) {
    await sql`UPDATE sage_accounts SET gl_account_id = ${glAccountId}::UUID, mapping_status = 'manual',
      mapping_notes = ${notes || 'Manually mapped'} WHERE sage_account_id = ${sageAccountId}`;
  } else {
    await sql`UPDATE sage_accounts SET gl_account_id = NULL, mapping_status = 'unmapped',
      mapping_notes = ${notes || null} WHERE sage_account_id = ${sageAccountId}`;
  }
}

// ── Comparison ──────────────────────────────────────────────────────────────

export async function generateComparison(companyId: string, userId: string): Promise<ComparisonReport> {
  try {
    const sageBalances = (await sql`
      SELECT sa.sage_account_id, sa.name, sa.balance, ga.account_code, ga.account_name, ga.id AS gl_id
      FROM sage_accounts sa JOIN gl_accounts ga ON ga.id = sa.gl_account_id ORDER BY ga.account_code
    `) as Row[];

    const glBalances = (await sql`
      SELECT ga.id, ga.account_code, ga.account_name, ga.normal_balance,
        COALESCE(SUM(jl.debit), 0) AS total_debit, COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
      WHERE ga.level >= 3 GROUP BY ga.id, ga.account_code, ga.account_name, ga.normal_balance ORDER BY ga.account_code
    `) as Row[];

    const glMap = new Map<string, number>();
    let glTotalDebit = 0; let glTotalCredit = 0;
    for (const gl of glBalances) {
      const d = Number(gl.total_debit), c = Number(gl.total_credit);
      glMap.set(String(gl.id), String(gl.normal_balance) === 'debit' ? d - c : c - d);
      glTotalDebit += d; glTotalCredit += c;
    }

    const differences: ComparisonReport['differences'] = [];
    let sageTotalDebit = 0; let sageTotalCredit = 0;
    for (const sage of sageBalances) {
      const sb = Number(sage.balance || 0), gb = glMap.get(String(sage.gl_id)) || 0;
      if (sb > 0) sageTotalDebit += sb; else sageTotalCredit += Math.abs(sb);
      if (Math.abs(sb - gb) > 0.01) {
        differences.push({ accountCode: String(sage.account_code), accountName: String(sage.account_name), sageBalance: sb, glBalance: gb, difference: sb - gb });
      }
    }

    const report: ComparisonReport = {
      comparisonDate: new Date().toISOString().slice(0, 10),
      sageTotals: { totalDebit: sageTotalDebit, totalCredit: sageTotalCredit, accountCount: sageBalances.length },
      glTotals: { totalDebit: glTotalDebit, totalCredit: glTotalCredit, accountCount: glBalances.length },
      differences, isBalanced: differences.length === 0,
    };

    await sql`
      INSERT INTO gl_migration_comparisons (comparison_date, sage_totals, gl_totals, differences, is_balanced, created_by)
      VALUES (${report.comparisonDate}, ${JSON.stringify(report.sageTotals)}, ${JSON.stringify(report.glTotals)},
        ${JSON.stringify(report.differences)}, ${report.isBalanced}, ${userId})
    `;
    return report;
  } catch (err) { log.error('Failed to generate comparison', { error: err }, 'accounting'); throw err; }
}

// ── Reset ───────────────────────────────────────────────────────────────────

export async function resetMigration(companyId: string, 
  runType: 'accounts' | 'ledger' | 'invoices' | 'customer_invoices'
): Promise<void> {
  if (runType === 'accounts') {
    await sql`UPDATE sage_accounts SET gl_account_id = NULL, mapping_status = 'unmapped', mapping_notes = NULL`;
  } else if (runType === 'ledger') {
    await sql`UPDATE sage_ledger_transactions SET migration_status = 'pending', gl_journal_entry_id = NULL`;
  } else if (runType === 'invoices') {
    await sql`UPDATE sage_supplier_invoices SET migration_status = 'pending', gl_supplier_invoice_id = NULL`;
  } else if (runType === 'customer_invoices') {
    await sql`UPDATE sage_customer_invoices SET migration_status = 'pending', gl_customer_invoice_id = NULL`;
  }
}

/**
 * PRD-060 Phase 6: Sage Data Importers
 * Ledger transaction → GL journal entries
 * Supplier invoices → AP supplier_invoices
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Ledger Transaction Import ───────────────────────────────────────────────

/**
 * Import sage_ledger_transactions as GL journal entries
 * Groups by document_number + transaction_date into balanced entries
 */
export async function importLedgerTransactions(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('ledger_import', userId);

  try {
    // Fetch all pending lines in a single SELECT — eliminates N+1 per-group queries
    const allLines = (await sql`
      SELECT slt.id, slt.document_number, slt.transaction_date, slt.description,
        slt.debit, slt.credit, slt.reference, slt.ff_project_id,
        sa.gl_account_id
      FROM sage_ledger_transactions slt
      JOIN sage_accounts sa ON sa.sage_account_id = slt.sage_account_id
      WHERE slt.migration_status = 'pending'
        AND sa.gl_account_id IS NOT NULL
      ORDER BY slt.transaction_date, slt.document_number
    `) as Row[];

    // Group lines in JavaScript rather than with a separate query per group
    const groupMap = new Map<string, { document_number: string; transaction_date: unknown; description: string; lines: Row[] }>();
    for (const line of allLines) {
      const key = `${line.document_number}::${String(line.transaction_date)}`;
      if (!groupMap.has(key)) {
        groupMap.set(key, {
          document_number: line.document_number,
          transaction_date: line.transaction_date,
          description: line.description,
          lines: [],
        });
      }
      groupMap.get(key)!.lines.push(line);
    }

    const groups = Array.from(groupMap.values());
    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const group of groups) {
      try {
        const lines = group.lines;
        if (lines.length === 0) { skipped++; continue; }

        const totalDebit = lines.reduce((s: number, l: Row) => s + Number(l.debit || 0), 0);
        const totalCredit = lines.reduce((s: number, l: Row) => s + Number(l.credit || 0), 0);

        if (Math.abs(totalDebit - totalCredit) > 0.02) {
          await transaction((txSql) =>
            lines.map(line => txSql`
              UPDATE sage_ledger_transactions SET migration_status = 'failed' WHERE id = ${line.id}
            `)
          );
          failed++;
          continue;
        }

        const entryRef = group.document_number
          ? `SAGE-${group.document_number}`
          : `SAGE-${group.transaction_date}`;

        const entry = (await sql`
          INSERT INTO gl_journal_entries (
            entry_number, entry_date, description, source, status, created_by
          ) VALUES (
            ${entryRef}, ${group.transaction_date},
            ${group.description || `Sage import: ${entryRef}`},
            'manual', 'posted', ${userId}
          ) RETURNING id
        `) as Row[];

        const entryId = String(entry[0].id);

        // Batch all line inserts + status updates into one HTTP round-trip
        const activeLines = lines.filter(l => Number(l.debit || 0) !== 0 || Number(l.credit || 0) !== 0);
        if (activeLines.length > 0) {
          await transaction((txSql) =>
            activeLines.flatMap(line => {
              const debit = Number(line.debit || 0);
              const credit = Number(line.credit || 0);
              const projectId = line.ff_project_id || null;
              const lineInsert = projectId
                ? txSql`
                    INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
                    VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                      ${line.description || group.description || ''}, ${projectId}::UUID)
                  `
                : txSql`
                    INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
                    VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                      ${line.description || group.description || ''})
                  `;
              const statusUpdate = txSql`
                UPDATE sage_ledger_transactions
                SET migration_status = 'imported', gl_journal_entry_id = ${entryId}::UUID
                WHERE id = ${line.id}
              `;
              return [lineInsert, statusUpdate];
            })
          );
        }

        succeeded++;
      } catch (err) {
        log.error('Failed to import ledger group', { docNum: group.document_number, error: err }, 'accounting');
        failed++;
      }
    }

    return await completeRun(runId, groups.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Supplier Invoice Import ─────────────────────────────────────────────────

/**
 * Import sage_supplier_invoices into the supplier_invoices table.
 * Matches Sage's approach: invoices are standalone AP documents,
 * no separate GL journal entries are created per invoice.
 */
export async function importSupplierInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_supplier_id, invoice_number,
        invoice_date, due_date, subtotal, tax_amount, total_amount,
        outstanding_amount, status, ff_purchase_order_id, supplier_id,
        raw_data, line_items
      FROM sage_supplier_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        // NOTE: purchase_orders table is not available in standalone accounting app.
        // Supplier ID must come from the Sage import data directly; PO lookup is stubbed.
        const supplierId = inv.supplier_id;

        if (!supplierId) {
          await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;

        // project_id cannot be resolved from purchase_orders in standalone mode
        const projectId: string | null = null;

        const isPaid = inv.status === 'paid' || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data if available
        const rawObj = parseJson(inv.raw_data);
        const reference = rawObj?.Reference || null;

        const newInv = (await sql`
          INSERT INTO supplier_invoices (
            invoice_number, supplier_id, purchase_order_id, project_id,
            invoice_date, due_date, subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${supplierId}, ${inv.ff_purchase_order_id || null}, ${projectId},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)}, ${totalAmount},
            ${isPaid ? totalAmount : 0}, ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id}, ${reference}, ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = parseRawData(inv.raw_data, inv.line_items);
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);
            const lineTaxPct = Number(line.TaxPercentage || 0) * 100;

            if (projectId) {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total, project_id
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal},
                  ${projectId}::UUID
                )
              `;
            } else {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal}
                )
              `;
            }
          }
        }

        await sql`
          UPDATE sage_supplier_invoices
          SET migration_status = 'imported', gl_supplier_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import sage invoice', { invoiceId: inv.id, error: err }, 'accounting');
        await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown, lineItems: unknown): any[] | null {
  // Try raw_data.Lines first (full Sage response with includeDetail)
  const raw = parseJson(rawData);
  if (raw?.Lines && Array.isArray(raw.Lines) && raw.Lines.length > 0) {
    return raw.Lines;
  }
  // Fall back to line_items JSONB column
  const items = parseJson(lineItems);
  if (Array.isArray(items) && items.length > 0) return items;
  return null;
}

function parseJson(val: unknown): Record<string, unknown> | null {
  if (!val) return null;
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch { return null; }
  }
  return val as Record<string, unknown>;
}

/**
 * Sage Customer Invoice Importer
 * Moves sage_customer_invoices → customer_invoices + customer_invoice_items
 * Matches Sage's approach: invoices are standalone AR documents,
 * no separate GL journal entries are created per invoice.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Import sage_customer_invoices into customer_invoices with line items
 */
export async function importCustomerInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('customer_invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_customer_id, client_id,
        invoice_number, invoice_date, due_date,
        subtotal, tax_amount, total_amount, outstanding_amount,
        status, raw_data
      FROM sage_customer_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        const clientId = inv.client_id;
        if (!clientId) {
          await sql`
            UPDATE sage_customer_invoices SET migration_status = 'failed'
            WHERE id = ${inv.id}
          `;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;
        const isPaid = inv.status === 'paid'
          || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data
        const rawData = parseRawData(inv.raw_data);
        const reference = rawData?.Reference || inv.invoice_number || null;

        const newInv = (await sql`
          INSERT INTO customer_invoices (
            invoice_number, client_id, invoice_date, due_date,
            billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${clientId}::UUID,
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)},
            ${totalAmount},
            ${isPaid ? totalAmount : 0},
            ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id},
            ${reference},
            ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = rawData?.Lines;
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);

            await sql`
              INSERT INTO customer_invoice_items (
                invoice_id, description, unit_price, quantity,
                tax_amount, line_total, income_type
              ) VALUES (
                ${newInvoiceId}::UUID,
                ${line.Description || 'Line item'},
                ${price}, ${qty}, ${lineTax}, ${lineTotal}, 'other'
              )
            `;
          }
        }

        await sql`
          UPDATE sage_customer_invoices
          SET migration_status = 'imported',
              gl_customer_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import customer invoice',
          { invoiceId: inv.id, error: err }, 'accounting');
        await sql`
          UPDATE sage_customer_invoices SET migration_status = 'failed'
          WHERE id = ${inv.id}
        `;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown): any {
  if (!rawData) return null;
  if (typeof rawData === 'string') {
    try { return JSON.parse(rawData); } catch { return null; }
  }
  return rawData;
}

-- Migration 206: Phase 1 Sage Alignment
-- Adds tables for: recurring invoices, write-offs, adjustments,
-- batch payments, recurring journals, VAT adjustments

-- ── Recurring Customer Invoices ─────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS recurring_invoices (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  template_name   TEXT NOT NULL,
  client_id       UUID NOT NULL REFERENCES customers(id),
  project_id      UUID,
  frequency       TEXT NOT NULL CHECK (frequency IN ('weekly','monthly','quarterly','annually')),
  next_run_date   DATE NOT NULL,
  end_date        DATE,
  last_run_date   DATE,
  run_count       INTEGER NOT NULL DEFAULT 0,
  status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','completed','cancelled')),
  description     TEXT,
  line_items      JSONB NOT NULL DEFAULT '[]',
  subtotal        NUMERIC(15,2) NOT NULL DEFAULT 0,
  tax_rate        NUMERIC(5,2) NOT NULL DEFAULT 15.00,
  tax_amount      NUMERIC(15,2) NOT NULL DEFAULT 0,
  total_amount    NUMERIC(15,2) NOT NULL DEFAULT 0,
  payment_terms   TEXT DEFAULT '30 days',
  created_by      UUID NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_recurring_invoices_client ON recurring_invoices(client_id);
CREATE INDEX IF NOT EXISTS idx_recurring_invoices_status ON recurring_invoices(status);
CREATE INDEX IF NOT EXISTS idx_recurring_invoices_next_run ON recurring_invoices(next_run_date) WHERE status = 'active';

-- ── Customer Write-Offs ─────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS customer_write_offs (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  write_off_number    TEXT NOT NULL UNIQUE,
  client_id           UUID NOT NULL REFERENCES customers(id),
  invoice_id          UUID NOT NULL REFERENCES customer_invoices(id),
  amount              NUMERIC(15,2) NOT NULL CHECK (amount > 0),
  reason              TEXT NOT NULL,
  write_off_date      DATE NOT NULL DEFAULT CURRENT_DATE,
  status              TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','cancelled')),
  gl_journal_entry_id UUID REFERENCES gl_journal_entries(id),
  approved_by         UUID,
  approved_at         TIMESTAMPTZ,
  created_by          UUID NOT NULL,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_write_offs_client ON customer_write_offs(client_id);
CREATE INDEX IF NOT EXISTS idx_write_offs_invoice ON customer_write_offs(invoice_id);
CREATE INDEX IF NOT EXISTS idx_write_offs_status ON customer_write_offs(status);

-- Auto-generate write-off numbers: WO-YYYY-NNNNN
CREATE OR REPLACE FUNCTION generate_write_off_number()
RETURNS TRIGGER AS $$
DECLARE
  next_num INTEGER;
  yr TEXT;
BEGIN
  yr := TO_CHAR(CURRENT_DATE, 'YYYY');
  SELECT COALESCE(MAX(CAST(SUBSTRING(write_off_number FROM 9) AS INTEGER)), 0) + 1
    INTO next_num
    FROM customer_write_offs
    WHERE write_off_number LIKE 'WO-' || yr || '-%';
  NEW.write_off_number := 'WO-' || yr || '-' || LPAD(next_num::TEXT, 5, '0');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_wo_number ON customer_write_offs;
CREATE TRIGGER trg_wo_number
  BEFORE INSERT ON customer_write_offs
  FOR EACH ROW
  WHEN (NEW.write_off_number IS NULL OR NEW.write_off_number = '')
  EXECUTE FUNCTION generate_write_off_number();

-- ── Adjustments (Customer & Supplier) ───────────────────────────────────────

CREATE TABLE IF NOT EXISTS accounting_adjustments (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  adjustment_number   TEXT NOT NULL UNIQUE,
  entity_type         TEXT NOT NULL CHECK (entity_type IN ('customer','supplier')),
  entity_id           UUID NOT NULL,
  adjustment_type     TEXT NOT NULL CHECK (adjustment_type IN ('debit','credit')),
  amount              NUMERIC(15,2) NOT NULL CHECK (amount > 0),
  reason              TEXT NOT NULL,
  adjustment_date     DATE NOT NULL DEFAULT CURRENT_DATE,
  status              TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','cancelled')),
  gl_journal_entry_id UUID REFERENCES gl_journal_entries(id),
  approved_by         UUID,
  approved_at         TIMESTAMPTZ,
  created_by          UUID NOT NULL,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_adjustments_entity ON accounting_adjustments(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_adjustments_status ON accounting_adjustments(status);

-- Auto-generate adjustment numbers: ADJ-YYYY-NNNNN
CREATE OR REPLACE FUNCTION generate_adjustment_number()
RETURNS TRIGGER AS $$
DECLARE
  next_num INTEGER;
  yr TEXT;
BEGIN
  yr := TO_CHAR(CURRENT_DATE, 'YYYY');
  SELECT COALESCE(MAX(CAST(SUBSTRING(adjustment_number FROM 10) AS INTEGER)), 0) + 1
    INTO next_num
    FROM accounting_adjustments
    WHERE adjustment_number LIKE 'ADJ-' || yr || '-%';
  NEW.adjustment_number := 'ADJ-' || yr || '-' || LPAD(next_num::TEXT, 5, '0');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_adj_number ON accounting_adjustments;
CREATE TRIGGER trg_adj_number
  BEFORE INSERT ON accounting_adjustments
  FOR EACH ROW
  WHEN (NEW.adjustment_number IS NULL OR NEW.adjustment_number = '')
  EXECUTE FUNCTION generate_adjustment_number();

-- ── Supplier Payment Batches ────────────────────────────────────────────────

