/**
 * Run SQL migration using Neon serverless driver
 * Usage: bun run scripts/run-migration.ts scripts/migrations/sql/220_multi_company_scoping.sql
 */
import { neon } from '@neondatabase/serverless';
import * as fs from 'node:fs';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('ERROR: DATABASE_URL environment variable is required.');
  process.exit(1);
}

const sqlFile = process.argv[2];
if (!sqlFile) {
  console.error('Usage: bun run scripts/run-migration.ts <path-to-sql-file>');
  process.exit(1);
}

const sqlContent = fs.readFileSync(sqlFile, 'utf-8');
const sql = neon(DATABASE_URL);

async function run() {
  console.log(`Running migration: ${sqlFile}`);
  console.log('Connecting to database...');

  // Split SQL into individual statements, handling $$ dollar-quoted blocks
  const statements: string[] = [];
  let current = '';
  let inDollarQuote = false;
  let inStatement = false;

  for (const line of sqlContent.split('\n')) {
    const trimmed = line.trim();

    // Skip pure comment/empty lines only when NOT in the middle of a statement
    if (!inStatement && !inDollarQuote && (trimmed.startsWith('--') || trimmed === '')) {
      continue;
    }

    // Track dollar-quoted blocks (CREATE FUNCTION bodies)
    if (trimmed.includes('$$')) {
      const count = (line.match(/\$\$/g) || []).length;
      if (count % 2 === 1) inDollarQuote = !inDollarQuote;
    }

    current += line + '\n';
    inStatement = true;

    // If we hit a semicolon at the end and we're not in a dollar-quoted block
    if (!inDollarQuote && trimmed.endsWith(';')) {
      const stmt = current.trim();
      if (stmt && stmt !== ';' && stmt !== 'BEGIN;' && stmt !== 'COMMIT;') {
        // Remove leading comment-only lines from the statement
        const cleaned = stmt.replace(/^(--[^\n]*\n)+/, '').trim();
        if (cleaned) statements.push(cleaned);
      }
      current = '';
      inStatement = false;
    }
  }

  console.log(`Found ${statements.length} statements to execute`);

  let success = 0;
  let errors = 0;

  for (let i = 0; i < statements.length; i++) {
    const stmt = statements[i];
    const preview = stmt.substring(0, 80).replace(/\n/g, ' ');
    try {
      await sql.query(stmt, []);
      success++;
      console.log(`  [${i + 1}/${statements.length}] OK: ${preview}...`);
    } catch (err: unknown) {
      errors++;
      const message = err instanceof Error ? err.message : String(err);
      console.error(`  [${i + 1}/${statements.length}] FAIL: ${preview}...`);
      console.error(`    Error: ${message}`);
    }
  }

  console.log(`\nMigration complete: ${success} succeeded, ${errors} failed out of ${statements.length} statements`);
}

run();

import pg from 'pg';
import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('ERROR: DATABASE_URL environment variable is required.');
  process.exit(1);
}

const client = new pg.Client({ connectionString: DATABASE_URL });

async function runMigrations() {
  console.log('=== Accounting Database Migration ===\n');

  await client.connect();
  console.log('Connected to database.\n');

  // Create migration tracking table
  await client.query(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      filename TEXT PRIMARY KEY,
      applied_at TIMESTAMPTZ DEFAULT NOW()
    )
  `);

  // Get already-applied migrations
  const applied = await client.query('SELECT filename FROM schema_migrations ORDER BY filename');
  const appliedSet = new Set(applied.rows.map(r => r.filename));

  // Discover all migration files in order
  const migrationsDir = join(process.cwd(), 'scripts/migrations/sql');
  const allFiles = readdirSync(migrationsDir)
    .filter(f => f.endsWith('.sql'))
    .sort();

  let newCount = 0;

  for (const migration of allFiles) {
    if (appliedSet.has(migration)) {
      continue; // Already applied
    }

    const filePath = join(migrationsDir, migration);
    try {
      const sqlContent = readFileSync(filePath, 'utf-8');
      console.log(`Running: ${migration}`);
      await client.query(sqlContent);
      await client.query('INSERT INTO schema_migrations (filename) VALUES ($1)', [migration]);
      console.log(`  ✓ Done\n`);
      newCount++;
    } catch (error) {
      console.error(`  ✗ Failed: ${error.message}\n`);
      // Fail fast on migration errors — don't leave schema in partial state
      console.error(`ABORTING: Fix the migration and re-run.`);
      await client.end();
      process.exit(1);
    }
  }

  if (newCount === 0) {
    console.log('All migrations already applied.\n');
  } else {
    console.log(`Applied ${newCount} new migration(s).\n`);
  }

  // Seed admin user if not exists
  console.log('Seeding admin user...');
  try {
    const bcrypt = await import('bcryptjs');
    const adminPassword = process.env.ADMIN_PASSWORD;
    if (!adminPassword) throw new Error('ADMIN_PASSWORD environment variable is required');
    const hash = await bcrypt.hash(adminPassword, 12);
    await client.query(`
      INSERT INTO users (id, email, password_hash, first_name, last_name, role, permissions, is_active)
      VALUES ($1, $2, $3, $4, $5, $6, $7::JSONB, $8)
      ON CONFLICT (email) DO NOTHING
    `, ['admin-001', 'admin@accounting.local', hash, 'Admin', 'User', 'super_admin', '["*"]', true]);
    console.log('  ✓ Admin user seeded\n');
  } catch (error) {
    console.error(`  ✗ Seed failed: ${error.message}\n`);
  }

  // Verify
  console.log('Verifying tables...');
  const result = await client.query(`
    SELECT tablename FROM pg_tables
    WHERE schemaname = 'public'
    ORDER BY tablename
  `);
  console.log(`  Found ${result.rows.length} tables:`);
  result.rows.forEach(t => console.log(`    - ${t.tablename}`));

  await client.end();
  console.log('\n=== Migration complete ===');
}

runMigrations().catch(err => {
  console.error('Fatal error:', err);
  client.end();
  process.exit(1);
});

/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig, Pool } from '@neondatabase/serverless';
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the Neon serverless driver.
 *
 * IMPORTANT: The Neon HTTP driver is stateless — each tagged template call is an
 * independent HTTP request. Issuing BEGIN/COMMIT as separate calls does NOT
 * guarantee they run on the same connection. We use the official `transaction()`
 * API from @neondatabase/serverless which batches queries into a single HTTP request.
 *
 * @param queries - Array of query-producing functions that receive the sql client
 * @returns Array of query results
 *
 * @example
 * const results = await transaction([
 *   (sql) => sql`INSERT INTO accounts (name) VALUES (${'Cash'}) RETURNING id`,
 *   (sql) => sql`UPDATE balances SET amount = 0 WHERE account_id = ${id}`,
 * ]);
 */
export async function transaction(
  queriesFn: (txSql: typeof sql) => Array<ReturnType<typeof sql>>
): Promise<unknown[]> {
  try {
    // Reuse module-level sql client instead of creating a new neon() client per call
    const results = await sql.transaction(
      (tx) => queriesFn(tx as unknown as typeof sql) as any,
      { isolationLevel: 'ReadCommitted' }
    );
    return results as unknown[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

/**
 * Execute a sequential, multi-step transaction using a dedicated pool client.
 *
 * Unlike `transaction()` above (which batches static queries in a single HTTP
 * round-trip), `withTransaction` allows intermediate `await` calls inside the
 * callback — necessary when later queries depend on IDs returned by earlier
 * inserts (INSERT … RETURNING id → INSERT … WHERE fk = id).
 *
 * The pool client issues genuine BEGIN / COMMIT / ROLLBACK, giving full ACID
 * guarantees. Any error thrown inside `fn` triggers an automatic ROLLBACK.
 *
 * @example
 * const invoiceId = await withTransaction(async (tx) => {
 *   const [row] = await tx`INSERT INTO invoices (total) VALUES (${total}) RETURNING id`;
 *   await tx`INSERT INTO invoice_items (invoice_id) VALUES (${row.id})`;
 *   return String(row.id);
 * });
 */
let _pool: Pool | null = null;

function getPool(): Pool {
  if (!_pool) {
    _pool = new Pool({ connectionString: getDatabaseUrl() });
  }
  return _pool;
}

// Type for a transaction-scoped sql tagged-template function
type TxSql = (strings: TemplateStringsArray, ...values: unknown[]) => Promise<unknown[]>;

export async function withTransaction<T>(fn: (tx: TxSql) => Promise<T>): Promise<T> {
  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Wrap the pool client's parameterised query as a tagged-template function
    // so callers can use tx`SELECT ...` instead of raw client.query strings.
    const tx: TxSql = async (strings, ...values) => {
      let text = '';
      strings.forEach((s, i) => {
        text += s;
        if (i < values.length) text += `$${i + 1}`;
      });
      const result = await client.query(text, values as unknown[]);
      return result.rows as unknown[];
    };

    const result = await fn(tx);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    log.error(
      'withTransaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  } finally {
    client.release();
  }
}

export default sql;

