async () => {
  // Pull full AR invoices and download
  const allAR = [];
  let skip = 0;
  let total = Infinity;
  while (skip < total) {
    const res = await fetch('/services/TaxInvoice/GetWithFilter', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json;charset=UTF-8' },
      body: JSON.stringify({ FilterId: 0, Search: '', Skip: skip, Take: 200 }),
      credentials: 'include'
    });
    const json = await res.json();
    total = json.TotalResults || 0;
    allAR.push(...(json.Results || []));
    skip += 200;
  }

  // Pull full customer receipts
  const allReceipts = [];
  skip = 0;
  total = Infinity;
  while (skip < total) {
    const res = await fetch('/services/CustomerReceipt/GetWithFilter', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json;charset=UTF-8' },
      body: JSON.stringify({ FilterId: 0, Search: '', Skip: skip, Take: 200 }),
      credentials: 'include'
    });
    const json = await res.json();
    total = json.TotalResults || 0;
    allReceipts.push(...(json.Results || []));
    skip += 200;
  }

  // Download both
  for (const [name, data] of [['sage-ar-invoices', allAR], ['sage-receipts', allReceipts]]) {
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name + '.json';
    a.click();
  }

  return { arInvoices: allAR.length, receipts: allReceipts.length };
}

